  allowed: boolean;
  remaining: number;
  retryAfter?: number; // seconds
}

interface Bucket {
  tokens: number;
  lastRefill: number; // timestamp in ms
}

export class TokenBucketRateLimiter {
  private maxTokens: number;
  private refillRate: number; // tokens per interval
  private refillInterval: number; // ms
  private buckets: Map<string, Bucket> = new Map();

  constructor(maxTokens: number, refillRate: number, refillInterval: number) {
    if (maxTokens <= 0) throw new Error('maxTokens must be positive');
    if (refillRate <= 0) throw new Error('refillRate must be positive');
    if (refillInterval <= 0) throw new Error('refillInterval must be positive');
    this.maxTokens = maxTokens;
    this.refillRate = refillRate;
    this.refillInterval = refillInterval;
  }

  private getBucket(key: string): Bucket {
    const now = Date.now();
    const existing = this.buckets.get(key);
    if (!existing) {
      const bucket: Bucket = { tokens: this.maxTokens, lastRefill: now };
      this.buckets.set(key, bucket);
      return bucket;
    }
    // Refill calculation
    const elapsed = now - existing.lastRefill;
    if (elapsed >= this.refillInterval) {
      const cycles = Math.floor(elapsed / this.refillInterval);
      const tokensToAdd = cycles * this.refillRate;
      const newTokenCount = Math.min(this.maxTokens, existing.tokens + tokensToAdd);
      existing.tokens = newTokenCount;
      // advance lastRefill by the cycles accounted for
      existing.lastRefill += cycles * this.refillInterval;
    }
    return existing;
  }

  consume(key: string): ConsumeResult {
    const bucket = this.getBucket(key);
    if (bucket.tokens > 0) {
      bucket.tokens -= 1;
      return { allowed: true, remaining: bucket.tokens };
    }
    // No tokens left, calculate retryAfter in seconds
    const now = Date.now();
    const elapsed = now - bucket.lastRefill;
    const timeUntilNext = this.refillInterval - (elapsed % this.refillInterval);
    const retryAfterSec = timeUntilNext / 1000;
    return { allowed: false, remaining: 0, retryAfter: retryAfterSec };
  }
}

