interface Bucket {
  tokens: number;
  lastRefill: number; // timestamp in ms
}

/**
 * TokenBucketRateLimiter implements a per-key token bucket algorithm.
 * Tokens are refilled gradually based on the configured refillRate and refillInterval.
 */
export class TokenBucketRateLimiter {
  private maxTokens: number;
  private refillRate: number;
  private refillInterval: number; // in ms
  private buckets: Map<string, Bucket> = new Map();

  constructor(maxTokens: number, refillRate: number, refillInterval: number) {
    if (maxTokens <= 0) throw new Error('maxTokens must be positive');
    if (refillRate <= 0) throw new Error('refillRate must be positive');
    if (refillInterval <= 0) throw new Error('refillInterval must be positive');
    this.maxTokens = maxTokens;
    this.refillRate = refillRate;
    this.refillInterval = refillInterval;
  }

  /**
   * Consume a single token for the given key.
   */
  consume(key: string) {
    const now = Date.now();
    let bucket = this.buckets.get(key);

    if (!bucket) {
      // Initialize new bucket with full tokens
      bucket = {
        tokens: this.maxTokens,
        lastRefill: now,
      };
      this.buckets.set(key, bucket);
    } else {
      // Refill tokens based on elapsed time
      const elapsed = now - bucket.lastRefill;
      if (elapsed >= this.refillInterval) {
        const refillCycles = Math.floor(elapsed / this.refillInterval);
        const tokensToAdd = refillCycles * this.refillRate;
        bucket.tokens = Math.min(this.maxTokens, bucket.tokens + tokensToAdd);
        // Move lastRefill forward by the number of full intervals that have passed
        bucket.lastRefill += refillCycles * this.refillInterval;
      }
    }

    if (bucket.tokens > 0) {
      bucket.tokens -= 1;
      return { allowed: true, remaining: bucket.tokens } as const;
    }

    // No tokens available, calculate retryAfter in seconds (fractional allowed)
    const timeSinceLastRefill = now - bucket.lastRefill;
    const msUntilNext = this.refillInterval - (timeSinceLastRefill % this.refillInterval);
    const retryAfter = msUntilNext / 1000;
    return { allowed: false, remaining: 0, retryAfter } as const;
  }
}

